PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS pack_metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_cards (id TEXT PRIMARY KEY, semantic_id TEXT NOT NULL UNIQUE, language_code TEXT NOT NULL, surface TEXT NOT NULL, register TEXT NOT NULL CHECK(register IN ('formal','neutral','informal')), translation TEXT, example TEXT, category TEXT, cefr TEXT, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quarantine_cards (id TEXT NOT NULL, semantic_id TEXT, language_code TEXT, surface TEXT, reasons_json TEXT NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(language_code,id));
CREATE INDEX IF NOT EXISTS idx_content_cards_semantic ON content_cards(semantic_id);
CREATE INDEX IF NOT EXISTS idx_content_cards_surface ON content_cards(surface);
CREATE INDEX IF NOT EXISTS idx_content_cards_category ON content_cards(category);
CREATE INDEX IF NOT EXISTS idx_quarantine_cards_semantic ON quarantine_cards(semantic_id);
DELETE FROM pack_metadata;
DELETE FROM content_cards;
DELETE FROM quarantine_cards;
PRAGMA user_version=1;
COMMIT;
